import json, csv
from pathlib import Path

json_path = Path('/root/trivy_report.json')
csv_path = Path('/root/security_audit.csv')

with json_path.open('r', encoding='utf-8') as f:
    data = json.load(f)

headers = ["Package","Version","CVE_ID","Severity","CVSS_Score","Fixed_Version","Title","Url"]

SEVERITIES = {"HIGH", "CRITICAL"}


def get_cvss_score(vuln):
    cvss = vuln.get('CVSS') or {}
    # Prefer v3 scores in NVD -> GHSA -> RedHat
    for source in ('nvd', 'ghsa', 'redhat'):
        source_data = cvss.get(source)
        if isinstance(source_data, dict):
            v3 = source_data.get('V3Score')
            if isinstance(v3, (int, float)):
                return v3
    # Fallback to NVD v2 if present
    nvd = cvss.get('nvd')
    if isinstance(nvd, dict):
        v2 = nvd.get('V2Score')
        if isinstance(v2, (int, float)):
            return v2
    return 'N/A'


def pick_url(vuln):
    primary = vuln.get('PrimaryURL')
    if primary:
        return primary
    refs = vuln.get('References')
    if isinstance(refs, list) and refs:
        return refs[0]
    return 'N/A'

records = []

for result in data.get('Results', []) or []:
    for vuln in result.get('Vulnerabilities', []) or []:
        severity = vuln.get('Severity') or 'UNKNOWN'
        if severity not in SEVERITIES:
            continue
        fixed = vuln.get('FixedVersion')
        if not fixed:
            fixed = 'N/A'
        record = {
            "Package": vuln.get('PkgName') or 'Unknown',
            "Version": vuln.get('InstalledVersion') or 'Unknown',
            "CVE_ID": vuln.get('VulnerabilityID') or 'N/A',
            "Severity": severity,
            "CVSS_Score": get_cvss_score(vuln),
            "Fixed_Version": fixed,
            "Title": vuln.get('Title') or vuln.get('Description') or 'N/A',
            "Url": pick_url(vuln),
        }
        records.append(record)

with csv_path.open('w', newline='', encoding='utf-8') as f:
    writer = csv.DictWriter(f, fieldnames=headers)
    writer.writeheader()
    writer.writerows(records)

print(f"Wrote {len(records)} records to {csv_path}")
